export function translate(text, language) {
  if (language !== "vi") return text;
  const key = text.replace(/\s+/g, " ").trim();
  if (vi[key]) return text.replace(text.trim(), vi[key]);
  let m;
  if ((m = key.match(/^(\d+) reps?\. (\d+) workouts?\.$/)))
    return `${m[1]} câu đã làm · ${m[2]} bài đã luyện`;
  if ((m = key.match(/^(\d+)% accuracy · saved on this device$/)))
    return `${m[1]}% đúng · lưu trên thiết bị này`;
  if ((m = key.match(/^Nearly\. The answer is (.+)\.$/)))
    return `Chưa đúng rồi. Đáp án là ${m[1]}.`;
  if ((m = key.match(/^Practice (\d+) missed questions? →$/)))
    return `Ôn lại ${m[1]} câu chưa đúng →`;
  if ((m = key.match(/^(\d+ \/ \d+) · review$/))) return `${m[1]} · ôn lại`;
  if (key.startsWith("Check the format. "))
    return "Kiểm tra cách nhập. " + translate(key.slice(18), language);
  if (
    (m = key.match(
      /^(NUMBERS|PRICES|TIMES|PHONES) \/ (WARM-UP|EVERYDAY|CHALLENGE)$/,
    ))
  )
    return (
      {
        NUMBERS: "SỐ ĐẾM",
        PRICES: "GIÁ TIỀN",
        TIMES: "GIỜ GIẤC",
        PHONES: "SỐ ĐIỆN THOẠI",
      }[m[1]] +
      " / " +
      { "WARM-UP": "KHỞI ĐỘNG", EVERYDAY: "HẰNG NGÀY", CHALLENGE: "THỬ THÁCH" }[
        m[2]
      ]
    );
  return text;
}
